from __future__ import annotations

import base64
import tempfile
import unittest
from pathlib import Path

from scripts import survey_reader_publication_v2 as publication


# Two-page PDF emitted by LuaLaTeX. Its Page dictionaries live in an ObjStm,
# which intentionally defeats raw `/Type /Page` byte scanning.
_LUALATEX_TWO_PAGE_PDF = base64.b64decode(
    ""
)


class SurveyPdfPageInspectionV2Tests(unittest.TestCase):
    def test_lualatex_object_stream_pdf_reports_exact_page_count(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "main.pdf"
            path.write_bytes(_LUALATEX_TWO_PAGE_PDF)
            self.assertEqual(publication._exact_pdf_page_count(path), 2)

    def test_invalid_pdf_fails_closed(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "main.pdf"
            path.write_bytes(b"not a pdf")
            with self.assertRaisesRegex(ValueError, "not deterministically inspectable"):
                publication._exact_pdf_page_count(path)


if __name__ == "__main__":
    unittest.main()
